package com.cognitivekernel.androidfit;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
public class WorkoutDb extends SQLiteOpenHelper {
 public WorkoutDb(Context c){super(c,"fit_yar.db",null,2);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE plans(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL)");d.execSQL("CREATE TABLE exercises(id INTEGER PRIMARY KEY AUTOINCREMENT,plan_id INTEGER NOT NULL,name TEXT NOT NULL,sets INTEGER NOT NULL,reps INTEGER NOT NULL)");d.execSQL("CREATE TABLE logs(id INTEGER PRIMARY KEY AUTOINCREMENT,date_jalali TEXT,plan_name TEXT,exercise_name TEXT,sets INTEGER,reps INTEGER,weight REAL,created_at INTEGER,rest_seconds INTEGER NOT NULL DEFAULT 60,effort INTEGER NOT NULL DEFAULT 7,notes TEXT NOT NULL DEFAULT '')");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2){d.execSQL("ALTER TABLE logs ADD COLUMN rest_seconds INTEGER NOT NULL DEFAULT 60");d.execSQL("ALTER TABLE logs ADD COLUMN effort INTEGER NOT NULL DEFAULT 7");d.execSQL("ALTER TABLE logs ADD COLUMN notes TEXT NOT NULL DEFAULT ''");}}
 public long addPlan(String n){if(n==null||n.trim().isEmpty())throw new IllegalArgumentException("Plan name is required");ContentValues v=new ContentValues();v.put("name",n.trim());return getWritableDatabase().insert("plans",null,v);}
 public long addExercise(long p,String n,int s,int r){if(n==null||n.trim().isEmpty()||s<1||r<1)throw new IllegalArgumentException("Exercise name, sets and reps must be valid");ContentValues v=new ContentValues();v.put("plan_id",p);v.put("name",n.trim());v.put("sets",s);v.put("reps",r);return getWritableDatabase().insert("exercises",null,v);}
 public boolean updateExercise(long id,String n,int s,int r){if(n==null||n.trim().isEmpty()||s<1||r<1)throw new IllegalArgumentException("Exercise name, sets and reps must be valid");ContentValues v=new ContentValues();v.put("name",n.trim());v.put("sets",s);v.put("reps",r);return getWritableDatabase().update("exercises",v,"id=?",new String[]{""+id})>0;}
 public void deleteExercise(long id){getWritableDatabase().delete("exercises","id=?",new String[]{""+id});}
 public void deletePlan(long id){SQLiteDatabase d=getWritableDatabase();d.delete("exercises","plan_id=?",new String[]{""+id});d.delete("plans","id=?",new String[]{""+id});}
 public List<String[]> plans(){List<String[]> a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name FROM plans ORDER BY name",null)){while(c.moveToNext())a.add(new String[]{c.getString(0),c.getString(1)});}return a;}
 public List<String[]> exercises(long p){List<String[]> a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,sets,reps FROM exercises WHERE plan_id=? ORDER BY id",new String[]{""+p})){while(c.moveToNext())a.add(new String[]{c.getString(0),c.getString(1),c.getString(2),c.getString(3)});}return a;}
 public void log(String date,String plan,String ex,int s,int r,double kg){logDetailed(date,plan,ex,s,r,kg,60,7,"");}
 public void logDetailed(String date,String plan,String ex,int s,int r,double kg,int rest,int effort,String notes){if(date==null||date.trim().isEmpty()||plan==null||plan.trim().isEmpty()||ex==null||ex.trim().isEmpty()||s<1||r<1||Double.isNaN(kg)||Double.isInfinite(kg)||kg<0||rest<0||effort<1||effort>10)throw new IllegalArgumentException("Workout log values must be valid");ContentValues v=new ContentValues();v.put("date_jalali",date);v.put("plan_name",plan);v.put("exercise_name",ex);v.put("sets",s);v.put("reps",r);v.put("weight",kg);v.put("created_at",System.currentTimeMillis());v.put("rest_seconds",rest);v.put("effort",effort);v.put("notes",notes==null?"":notes.trim());getWritableDatabase().insert("logs",null,v);}
 public Cursor allLogs(){return getReadableDatabase().rawQuery("SELECT date_jalali,plan_name,exercise_name,sets,reps,weight,rest_seconds,effort,notes FROM logs ORDER BY created_at DESC",null);}
 public Cursor summary(){return getReadableDatabase().rawQuery("SELECT COUNT(*),COUNT(DISTINCT date_jalali),COALESCE(SUM(sets*reps*weight),0),COALESCE(MAX(weight),0) FROM logs",null);}
 public Cursor recentLogs(){return getReadableDatabase().rawQuery("SELECT date_jalali,exercise_name,sets,reps,weight,effort,notes FROM logs ORDER BY created_at DESC LIMIT 30",null);}
 public int weeklyTrainingDays(){try(Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(DISTINCT date_jalali) FROM logs WHERE created_at>=?",new String[]{String.valueOf(System.currentTimeMillis()-7L*24*60*60*1000)})){return c.moveToFirst()?c.getInt(0):0;}}
 public Cursor volumeByDate(){return getReadableDatabase().rawQuery("SELECT date_jalali,COALESCE(SUM(sets*reps*weight),0) FROM logs GROUP BY date_jalali ORDER BY MIN(created_at) DESC LIMIT 7",null);}
}
